import React, {useCallback} from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Dimensions,
} from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
} from 'react-native-reanimated';
import {
  GestureDetector,
  Gesture,
  GestureHandlerRootView,
} from 'react-native-gesture-handler';

const {width} = Dimensions.get('window');
const DRAWER_WIDTH = 250;

const DocumentScreen = () => {
  const translateX = useSharedValue(-DRAWER_WIDTH);

  const openDrawer = useCallback(() => {
    translateX.value = withSpring(0, {damping: 15});
  }, []);

  const closeDrawer = useCallback(() => {
    translateX.value = withSpring(-DRAWER_WIDTH, {damping: 15});
  }, []);

  const panGesture = Gesture.Pan()
    .onUpdate(event => {
      translateX.value = Math.min(
        0,
        Math.max(-DRAWER_WIDTH, event.translationX),
      );
    })
    .onEnd(() => {
      if (translateX.value > -DRAWER_WIDTH / 2) {
        openDrawer();
      } else {
        closeDrawer();
      }
    });

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{translateX: translateX.value}],
  }));

  return (
    <GestureHandlerRootView>
      <View style={styles.container}>
        {/* Gesture Detector cho phép kéo để mở/đóng */}
        <GestureDetector gesture={panGesture}>
          <Animated.View style={[styles.drawer, animatedStyle]}>
            <Text style={styles.menuText}>🏠 Home</Text>
            <Text style={styles.menuText}>🔍 Search</Text>
            <Text style={styles.menuText}>⚙️ Settings</Text>
            <TouchableOpacity onPress={closeDrawer} style={styles.closeButton}>
              <Text style={styles.buttonText}>Close</Text>
            </TouchableOpacity>
          </Animated.View>
        </GestureDetector>

        {/* Nút mở Drawer */}
        <TouchableOpacity onPress={openDrawer} style={styles.openButton}>
          <Text style={styles.buttonText}>Open Menu</Text>
        </TouchableOpacity>
      </View>
    </GestureHandlerRootView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f5f5f5',
    justifyContent: 'center',
    alignItems: 'center',
  },
  drawer: {
    position: 'absolute',
    left: 0,
    top: 0,
    bottom: 0,
    width: DRAWER_WIDTH,
    backgroundColor: '#333',
    padding: 20,
    justifyContent: 'center',
  },
  menuText: {color: 'white', fontSize: 18, marginBottom: 20},
  closeButton: {
    marginTop: 20,
    padding: 10,
    backgroundColor: '#d9534f',
    borderRadius: 5,
  },
  openButton: {padding: 15, backgroundColor: '#007bff', borderRadius: 5},
  buttonText: {color: 'white', fontSize: 18},
});

export default DocumentScreen;
