import {BASE_URL} from './httpClient';

export const createNotificationService = (fetchRequest: any) => ({
  async getDataNotification(params: any, sort: any) {
    try {
      const endpoint = '/services/notify/api/notifications/tasks/all';
      const uri =
        BASE_URL +
        endpoint +
        `?sort=${sort.sort}&sort=${sort.sort2}&page=${params.page}&size=${params.size}&search=${params.search}` +
        (sort.sort3 ? `&sort=${sort.sort3}` : '');
      const response = await fetchRequest({
        url: uri,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      const totalPage = Math.ceil(response.headers['x-total-count'] / 10);
      return Promise.resolve({
        data: response.data,
        totalPage,
      });
    } catch (error) {
      console.log('err sendNotification', error);
      return Promise.reject(error);
    }
  },

  async putProcessing(body: any) {
    try {
      const endpoint = '/services/notify/api/notifications/status/processing_1';
      const resp = await fetchRequest({
        url: BASE_URL + endpoint,
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(resp.data);
    } catch (error) {
      console.log('err putProcessing', error);
      return Promise.reject(error);
    }
  },

  async signDozen(body: any) {
    try {
      const endpoint = '/services/excall/api/excalls';
      const resp = await fetchRequest({
        url: BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(resp.data);
    } catch (error) {
      console.log('err signDozen', error);
      return Promise.reject(error);
    }
  },

  async getJwtTokenSignature(body: any) {
    try {
      const endpoint = '/services/envelope/api/p/auth/login/recipient';
      const resp = await fetchRequest({
        url: BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(resp.data);
    } catch (error) {
      console.log('err getJwtTokenSignature', error);
      return Promise.reject(error);
    }
  },

  async convertImage300250(body: any) {
    try {
      const endpoint =
        '/services/envelope/api/p/envelope/multimediaProcessing/image/lightPhoto/300/250';
      const resp = await fetchRequest({
        url: BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'text/plain',
        },
        body: JSON.stringify(body),
        typeOfResponse: 'text',
      });
      return Promise.resolve(resp.data);
    } catch (error) {
      console.log('err convertImage300250', error);
      return Promise.reject(error);
    }
  },
});
