import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {getListStatus} from './helper';
import {GroupData} from '../../helper';
import TextCM from '../../../../../../../components/Text';
import {IconBlackDown} from '../../../../../../../assets/images';
import BottomSheetCM from '../../../../../../../components/BottomSheet';
import GroupRadio from '../../../../../../../components/GroupRadio';

type Props = {
  value?: GroupData;
  onPicType: (value: GroupData | undefined) => void;
};

const PicStatusView = ({value, onPicType}: Props) => {
  const {t} = useTranslation();

  const [isVisible, setIsVisible] = useState<boolean>(false);

  const togglePicType = () => {
    setIsVisible(!isVisible);
  };

  return (
    <>
      <TouchableOpacity style={styles.btnPicType} onPress={togglePicType}>
        {value ? (
          <View>
            <TextCM style={styles.txtLabel}>{t('NT.modal.TxtStatus')}</TextCM>
            <TextCM style={styles.txtType}>{value?.label}</TextCM>
          </View>
        ) : (
          <TextCM style={styles.txtNoType}>{t('NT.modal.TxtStatus')}</TextCM>
        )}
        <IconBlackDown width={16} height={16} />
      </TouchableOpacity>
      <BottomSheetCM
        renderContent={
          <ContentPicTypeView value={value} onPicType={onPicType} />
        }
        title={t('NT.modal.TxtStatus')}
        onClose={togglePicType}
        isVisible={isVisible}
      />
    </>
  );
};

type ContentPicTypeViewProps = {
  value?: GroupData;
  onPicType: (value: GroupData | undefined) => void;
};

const ContentPicTypeView = ({value, onPicType}: ContentPicTypeViewProps) => {
  const {t} = useTranslation();

  return (
    <View style={styles.viewPicType}>
      <TextCM style={styles.txtTitlePicType}>
        {t('NT.modal.TxtPicStatus')}
      </TextCM>
      <GroupRadio
        data={getListStatus() as GroupData[]}
        onPressData={onPicType}
        currentValue={value as GroupData}
        containerStyle={styles.viewGroupRadio}
      />
    </View>
  );
};

export default PicStatusView;
